package com.payresolve.investigator.model;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;

import java.util.ArrayList;
import java.util.List;

/**
 * Structured output report generated by the AI Investigator agent and validated by the verifier.
 */
@JsonIgnoreProperties(ignoreUnknown = true)
public record InvestigationReport(
    @JsonProperty("status") String status,
    @JsonProperty("confirmed") List<ConfirmedFact> confirmed,
    @JsonProperty("conflicts") List<ConflictFact> conflicts,
    @JsonProperty("missing") List<MissingItem> missing,
    @JsonProperty("recommendedAction") RecommendedAction recommendedAction,
    @JsonProperty("degraded") Boolean degraded,
    @JsonProperty("explanation") String explanation
) {
    public InvestigationReport {
        confirmed = confirmed != null ? List.copyOf(confirmed) : List.of();
        conflicts = conflicts != null ? List.copyOf(conflicts) : List.of();
        missing = missing != null ? List.copyOf(missing) : List.of();
        degraded = degraded != null && degraded;
    }

    public List<String> allCitedEvidenceIds() {
        List<String> ids = new ArrayList<>();
        for (ConfirmedFact f : confirmed) {
            ids.addAll(f.evidenceIds());
        }
        for (ConflictFact c : conflicts) {
            ids.addAll(c.evidenceIds());
        }
        if (recommendedAction != null && recommendedAction.evidenceIds() != null) {
            ids.addAll(recommendedAction.evidenceIds());
        }
        return ids;
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record ConfirmedFact(
        @JsonProperty("statement") String statement,
        @JsonProperty("evidenceIds") List<String> evidenceIds
    ) {
        public ConfirmedFact {
            evidenceIds = evidenceIds != null ? List.copyOf(evidenceIds) : List.of();
        }
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record ConflictFact(
        @JsonProperty("statement") String statement,
        @JsonProperty("evidenceIds") List<String> evidenceIds
    ) {
        public ConflictFact {
            evidenceIds = evidenceIds != null ? List.copyOf(evidenceIds) : List.of();
        }
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record MissingItem(
        @JsonProperty("item") String item,
        @JsonProperty("why") String why
    ) {}

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record RecommendedAction(
        @JsonProperty("type") String type,
        @JsonProperty("rationale") String rationale,
        @JsonProperty("evidenceIds") List<String> evidenceIds
    ) {
        public RecommendedAction {
            evidenceIds = evidenceIds != null ? List.copyOf(evidenceIds) : List.of();
        }
    }
}

